### 参考解答

令 \(d=a+b-c\)。在每一位上，两个数的数字之和可以写成“结果位 + \(k\) 的倍数”，因此必有
\[
a+b-c=kM
\]
其中 \(M\ge 0\) 是整数。所以候选进制 \(k\) 必须整除 \(d\)。

- 若 \(d<0\)，不可能有解。
- 若 \(d=0\)，取任意 \(k>a+b\)，三个数都能按所需方式相加，因此有无穷多个进制，输出 `-1`。
- 若 \(d>0\)，枚举 \(d\) 的所有不小于 2 的因子，再逐位验证该进制下的不进位加法结果是否为 \(c\)。

```cpp
#include <bits/stdc++.h>
using namespace std;

bool valid(long long k, long long a, long long b, long long c) {
    while (a > 0 || b > 0 || c > 0) {
        long long x = a % k;
        long long y = b % k;
        long long z = c % k;

        if ((x + y) % k != z) return false;

        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;

        long long d = a + b - c;

        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int answer = 0;

            for (long long i = 1; i <= d / i; ++i) {
                if (d % i != 0) continue;

                long long j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++answer;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++answer;
